using UnityEngine; using UnityEditor; using UnityEngine.SceneManagement; using UnityEditor.SceneManagement; public static class MissingScriptCleaner { [MenuItem("Tools/Clean Missing Scripts In Scene")] public static void Run() { int removed = 0; foreach (var go in Object.FindObjectsByType<GameObject>(FindObjectsInactive.Include, FindObjectsSortMode.None)) { removed += GameObjectUtility.RemoveMonoBehavioursWithMissingScript(go); } EditorSceneManager.MarkSceneDirty(EditorSceneManager.GetActiveScene()); Debug.Log($"Removed {removed} missing scripts."); } }
